#!/usr/bin/env bash
# Runs the Go test suite against a real PostgreSQL instead of the SQLite fallback.
#
# The suite defaults to SQLite because it needs nothing installed, and that let
# two defects reach production while every test passed:
#
#   - a duplicate-detection query used LIKE on payload_json. That column is TEXT
#     in SQLite and JSONB in PostgreSQL, which has no LIKE for JSONB, so every
#     ingest failed with SQLSTATE 42883.
#   - reviewing a proposed relation reused one parameter for two columns, and
#     PostgreSQL deduced conflicting types for it, so every approve and reject
#     returned HTTP 500.
#
# SQLite also ignores ASCII case in LIKE where PostgreSQL does not, so a search
# that matches under the fallback can return nothing in production.
#
# Starts a throwaway container, runs the suite against it, and removes it.
set -euo pipefail

root=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
container=${POSTGRES_CONTAINER:-invenqor-pgtest}
port=${POSTGRES_PORT:-55432}
image=${POSTGRES_IMAGE:-postgres:17-alpine}

# A configured credential helper that fails takes every pull down with it, and
# this is a public image that needs no credentials.
if [ -z "${DOCKER_CONFIG:-}" ]; then
  docker_config=$(mktemp -d)
  echo '{}' > "$docker_config/config.json"
  export DOCKER_CONFIG="$docker_config"
fi

cleanup() {
  docker rm -f "$container" >/dev/null 2>&1 || true
  [ -n "${docker_config:-}" ] && rm -rf "$docker_config"
}
trap cleanup EXIT

docker rm -f "$container" >/dev/null 2>&1 || true
docker run -d --name "$container" \
  -e POSTGRES_PASSWORD=test -e POSTGRES_DB=invenqor \
  -p "$port:5432" "$image" >/dev/null

ready=0
for _ in $(seq 1 60); do
  if docker exec "$container" pg_isready -U postgres >/dev/null 2>&1; then
    ready=1
    break
  fi
done
[ "$ready" -eq 1 ] || { echo "PostgreSQL did not become ready" >&2; exit 1; }

export INVENQOR_TEST_POSTGRES_DSN="postgres://postgres:test@127.0.0.1:$port/invenqor?sslmode=disable"
cd "$root/server"
echo "running the suite against $image"
go test "$@" ./...
package httpapi

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/hkjang/invenqor/server/internal/auth"
	"github.com/hkjang/invenqor/server/internal/storage"
	"github.com/hkjang/invenqor/server/internal/storagetest"
)

func authenticateInitialAdmin(
	t *testing.T,
	server *Server,
	runtime *storage.Runtime,
) (*http.Cookie, string) {
	t.Helper()
	token, err := os.ReadFile(
		filepath.Join(storagetest.StateDir(t, runtime), "initial-admin.token"),
	)
	if err != nil {
		t.Fatalf("read bootstrap token: %v", err)
	}
	create := performJSON(
		t,
		server,
		http.MethodPost,
		"/api/v1/bootstrap/admin",
		map[string]string{
			"username":     "admin.user",
			"password":     "CorrectHorse!42",
			"display_name": "Administrator",
		},
		map[string]string{
			"X-Invenqor-Bootstrap-Token": strings.TrimSpace(string(token)),
		},
	)
	if create.Code != http.StatusCreated {
		t.Fatalf(
			"create initial admin status = %d body = %s",
			create.Code,
			create.Body.String(),
		)
	}
	login := performJSON(
		t,
		server,
		http.MethodPost,
		"/api/v1/auth/local/login",
		map[string]string{
			"username": "admin.user",
			"password": "CorrectHorse!42",
		},
		nil,
	)
	if login.Code != http.StatusOK {
		t.Fatalf(
			"login status = %d body = %s",
			login.Code,
			login.Body.String(),
		)
	}
	var payload struct {
		CSRFToken string `json:"csrf_token"`
	}
	if err := json.Unmarshal(login.Body.Bytes(), &payload); err != nil {
		t.Fatalf("decode login response: %v", err)
	}
	for _, cookie := range login.Result().Cookies() {
		if cookie.Name == auth.SessionCookie {
			return cookie, payload.CSRFToken
		}
	}
	t.Fatal("login response omitted session cookie")
	return nil, ""
}

func performAuthenticatedJSON(
	t *testing.T,
	server *Server,
	method string,
	path string,
	body any,
	cookie *http.Cookie,
	csrf string,
) *httptest.ResponseRecorder {
	t.Helper()
	bytesBody, err := json.Marshal(body)
	if err != nil {
		t.Fatalf("json.Marshal() error = %v", err)
	}
	request := httptest.NewRequest(method, path, bytes.NewReader(bytesBody))
	request.Header.Set("Content-Type", "application/json")
	request.Header.Set("X-CSRF-Token", csrf)
	request.AddCookie(cookie)
	authenticated := httptest.NewRecorder()
	server.Handler().ServeHTTP(authenticated, request)
	return authenticated
}

